await story('P2-regression-publish-grant-answer',async()=>{
 await local.p.locator('.hub-exposure input[role=switch]').waitFor();await local.p.locator('.hub-exposure input[role=switch]').click();await local.p.locator('.hub-exposure.is-shared a').waitFor();grantUrl=await local.p.locator('.hub-exposure.is-shared a').getAttribute('href');exposureId=new URL(grantUrl).searchParams.get('agent');await owner.p.goto(grantUrl);await owner.p.locator('.hub-grant input').fill('asker');await owner.p.locator('.dlg-actions .btn-primary').click();await owner.p.locator('.hub-grant').waitFor({state:'detached'});const clean=new URL(grantUrl);clean.searchParams.delete('grant');globalThis.p2AgentUrl=clean.href;await owner.p.goto(clean.href);
 asker=await context(cases[0]);await signIn(asker.p,'asker');await asker.p.locator('[data-entry=chat] button').click();await asker.p.locator('.hub-pick-row button').first().click();await asker.p.locator('#msgIn').waitFor();roomUrl=asker.p.url();await asker.p.fill('#msgIn','Pass2 department question');await asker.p.locator('#sendBtn').click();await waitFor(()=>deliveries.length===1,'first question reaches actual representative');await pauseMs(200);receipt.firstAnswer=await reportHook({correlationId:deliveries[0].correlationId,caller:'general',text:'Pass2 department answer',callerCurrent:()=>globalThis.p2Primary.live});await asker.p.getByText('Pass2 department answer',{exact:true}).waitFor();check('actual full-pipeline answer visible',receipt.firstAnswer.ok);await shot(asker.p,'P2-first-answer');
 const no=await context(cases[1]);try{await signIn(no.p,'outsider',new URL(roomUrl).pathname+new URL(roomUrl).search);await no.p.locator('.hub-chat').waitFor();await pauseMs(800);check('other department gets no protected answer',await no.p.getByText('Pass2 department answer',{exact:true}).count()===0);await shot(no.p,'P2-outsider-stale-room');}finally{await no.ctx.close();}
});
await story('P2-A8-12-complete-negative-restored-resume',async()=>{
 const before=deliveries.length;person('asker').groups=[GROUP_C];const r1=asker.p.waitForResponse(r=>new URL(r.url()).pathname.endsWith('/messages')&&r.request().method()==='POST');await asker.p.fill('#msgIn','Blocked after complete group removal');await asker.p.locator('#sendBtn').click();const denied=await r1;receipt.groupRemovalReply={status:denied.status(),body:await denied.json()};check('complete negative refuses actual send',!denied.ok());await admin.p.goto(origin+'/ui/hub/admin?view=groups');await admin.p.locator(`[data-paused="${person('asker').id}"]`).waitFor();check('no input after group removal',deliveries.length===before);await shot(admin.p,'P2-A8-12-durable-pause');await shot(asker.p,'P2-A8-12-send-refused');
 person('asker').groups=['bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'];await asker.p.reload();await asker.p.locator('#msgIn').waitFor();const r2=asker.p.waitForResponse(r=>new URL(r.url()).pathname.endsWith('/messages')&&r.request().method()==='POST');await asker.p.fill('#msgIn','Rejoin must still require Resume');await asker.p.locator('#sendBtn').click();const still=await r2;receipt.restoredBeforeResumeReply={status:still.status(),body:await still.json()};check('restored group alone refuses actual send',!still.ok()&&deliveries.length===before);await shot(asker.p,'P2-A8-12-restored-no-resume');
 await admin.p.locator(`[data-paused="${person('asker').id}"] button`).click();await admin.p.locator(`[data-paused="${person('asker').id}"]`).waitFor({state:'detached'});await asker.p.reload();await asker.p.locator('#msgIn').waitFor();await asker.p.fill('#msgIn','Explicit Resume restores the next question');await asker.p.locator('#sendBtn').click();await waitFor(()=>deliveries.length===before+1,'resumed input reaches representative');await pauseMs(200);receipt.resumeAnswer=await reportHook({correlationId:deliveries.at(-1).correlationId,caller:'general',text:'Pass2 resumed answer',callerCurrent:()=>globalThis.p2Primary.live});await asker.p.getByText('Pass2 resumed answer',{exact:true}).waitFor();check('exact Resume restores answer',receipt.resumeAnswer.ok);await shot(asker.p,'P2-A8-12-resumed-answer');
});
await story('P2-regression-revoke-held-answer',async()=>{
 const before=deliveries.length;await asker.p.fill('#msgIn','Hold this Pass2 answer across grant revocation');await asker.p.locator('#sendBtn').click();await waitFor(()=>deliveries.length===before+1,'held answer input');await pauseMs(200);await owner.p.goto(globalThis.p2AgentUrl);await owner.p.getByRole('button',{name:'More for asker',exact:true}).click();await owner.p.getByRole('menuitem',{name:'Revoke…',exact:true}).click();await owner.p.locator('.dlg-actions .btn-danger').click();await owner.p.getByRole('button',{name:'More for asker',exact:true}).waitFor({state:'detached'});receipt.heldAnswer=await reportHook({correlationId:deliveries.at(-1).correlationId,caller:'general',text:'PASS2_HELD_MUST_NOT_DISCLOSE',callerCurrent:()=>globalThis.p2Primary.live});check('late answer release refused',receipt.heldAnswer.ok===false);await asker.p.reload();await asker.p.locator('.hub-chat').waitFor();await pauseMs(1000);check('late protected text absent',!(await asker.p.locator('body').innerText()).includes('PASS2_HELD_MUST_NOT_DISCLOSE'));await shot(asker.p,'P2-revoked-room');await local.p.reload();await local.p.locator('.hub-exposure.is-shared input').click();await local.p.locator('.hub-exposure.is-shared').waitFor({state:'detached'});
});
